#!/usr/bin/env bash
# run_all.sh -- every check outside Lean; outputs go to build/.
#   C:      h1check.c rebuilds K and L, checks that both are semidistributive, that the diagonal is a
#           maximal sublattice of L whose complement has two minimal and two maximal elements, and lists
#           the sublattices of K x K generated by the diagonal and one further pair
#   Python: check_paper.py recomputes every number printed in preprint/main.tex (tables, pair list, the
#           cycle (4.1), footnote, remarks); single_pair_search.py decides, by SAT, for each sublattice
#           generated by the diagonal and one pair whether it is a counterexample (needs python-sat)
#   Lean:   gen_lean.py must reproduce lean/H1/Counterexample.lean exactly
# Needs a C compiler and Python 3 with python-sat.
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
B="$ROOT/build"
PY="$ROOT/verification/python"
mkdir -p "$B"
cd "$ROOT"

echo "== C: the counterexample"
cc -O2 -Wall -Wextra -Werror -o "$B/h1check" verification/c/h1check.c
"$B/h1check" | tee "$B/h1check.txt"
diff <(grep '^single pairs' "$B/h1check.txt") data/single_pair_sizes.txt

echo "== Python: every number in the paper"
python3 -I "$PY/check_paper.py" preprint/main.tex | tee "$B/check_paper.txt"

echo "== Python: sublattices generated by the diagonal and one pair"
python3 -I "$PY/single_pair_search.py" | tee "$B/single_pair_search.txt"

echo "== the Lean file is the generator's output"
cp lean/H1/Counterexample.lean "$B/Counterexample.lean.orig"
python3 -I scripts/gen_lean.py
cmp lean/H1/Counterexample.lean "$B/Counterexample.lean.orig"
echo "all checks passed"
